use serde::{Deserialize, Serialize};
use std::collections::HashMap;

# [test] fn path_prefix_remapping () { { let mapping = & FilePathMapping :: new (vec ! [(path ("abc/def") , path ("foo"))] , FileNameDisplayPreference :: Remapped , FileNameEmbeddablePreference :: RemappedOnly ,) ; assert_eq ! (map_path_prefix (mapping , "abc/def/src/main.rs") , path_str ("foo/src/main.rs")) ; assert_eq ! (map_path_prefix (mapping , "abc/def") , path_str ("foo")) ; } { let mapping = & FilePathMapping :: new (vec ! [(path ("abc/def") , path ("/foo"))] , FileNameDisplayPreference :: Remapped , FileNameEmbeddablePreference :: RemappedOnly ,) ; assert_eq ! (map_path_prefix (mapping , "abc/def/src/main.rs") , path_str ("/foo/src/main.rs")) ; assert_eq ! (map_path_prefix (mapping , "abc/def") , path_str ("/foo")) ; } { let mapping = & FilePathMapping :: new (vec ! [(path ("/abc/def") , path ("foo"))] , FileNameDisplayPreference :: Remapped , FileNameEmbeddablePreference :: RemappedOnly ,) ; assert_eq ! (map_path_prefix (mapping , "/abc/def/src/main.rs") , path_str ("foo/src/main.rs")) ; assert_eq ! (map_path_prefix (mapping , "/abc/def") , path_str ("foo")) ; } { let mapping = & FilePathMapping :: new (vec ! [(path ("/abc/def") , path ("/foo"))] , FileNameDisplayPreference :: Remapped , FileNameEmbeddablePreference :: RemappedOnly ,) ; assert_eq ! (map_path_prefix (mapping , "/abc/def/src/main.rs") , path_str ("/foo/src/main.rs")) ; assert_eq ! (map_path_prefix (mapping , "/abc/def") , path_str ("/foo")) ; } }